import{_ as t,C as r,o,c as i,E as c,a2 as n}from"./chunks/framework.Cm6XCzck.js";const y=JSON.parse('{"title":"检查点，不是恢复合同","description":"","frontmatter":{"title":"检查点，不是恢复合同","date":"2026-09-03","column":"digital-employee","category":"daily","article_type":"technical-analysis","edition":"research-center","research_question":"检查点必须绑定哪些要素，才能让长期运行的数字员工恢复为同一项可问责工作，而不是只从旧文件状态重新开始？","summary":"对齐智能体上下文与工作区的检查点能改善长时任务恢复，却不能撤回网络或外部服务中的既有影响。可问责恢复还必须绑定工作发生、恢复权限、策略版本与外部影响台账。","sources":["research/analysis/Q-20260903-01-aligned-checkpoint-recovery-boundary.md"],"item_id":"Q-20260903-01","lifecycle":"Published","cover":"/assets/covers/daily-2026-09-03-a-checkpoint-is-not-a-recovery-contract-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/digital-employee/2026-09-03-a-checkpoint-is-not-a-recovery-contract.md","filePath":"zh/digital-employee/2026-09-03-a-checkpoint-is-not-a-recovery-contract.md","lastUpdated":1788445576000}'),s={name:"zh/digital-employee/2026-09-03-a-checkpoint-is-not-a-recovery-contract.md"};function p(l,e,d,h,m,u){const a=r("ArticleCover");return o(),i("div",null,[c(a,{image:"/assets/covers/daily-2026-09-03-a-checkpoint-is-not-a-recovery-contract-cover.png",kicker:"数字员工 · 每日研究",title:"检查点，不是恢复合同",summary:"对齐智能体上下文与工作区的检查点能改善长时任务恢复，却不能撤回网络或外部服务中的既有影响。可问责恢复还必须绑定工作发生、恢复权限、策略版本与外部影响台账。",version:"Q-20260903-01",status:"Daily Runtime V5 · 2026-09-03",languageHref:"/en/digital-employee/2026-09-03-a-checkpoint-is-not-a-recovery-contract",languageLabel:"English"}),e[0]||(e[0]=n('<h1 id="检查点-不是恢复合同" tabindex="-1">检查点，不是恢复合同 <a class="header-anchor" href="#检查点-不是恢复合同" aria-label="Permalink to &quot;检查点，不是恢复合同&quot;">​</a></h1><p>一个数字员工在发送客户通知后中断。系统把它的上下文和工作区一起回退到发送之前：文件一致了，推理前提也一致了，但通知并没有从收件人的邮箱里消失。如果恢复后的执行再次发送，技术上成功的回退就会制造重复影响。</p><p>这说明两个问题经常被混为一谈：能否恢复状态，与是否有权继续同一项工作。检查点回答前一个问题；后一个问题还需要执行发生、当前权限和外部影响的证据。</p><p>一项关于长时工程任务的一手研究提出智能体上下文与受控工作区的对齐回退。论文在 82 个任务上报告，相比继续执行、携带经验重启等基线，这种方法提高了任务成功率和清单进度；组件消融也显示，环境回退、上下文回退和失败记忆具有互补作用。但研究同时划定了边界：工作区能够回退，网络请求、外部服务调用和外部运行状态不会随之撤销。</p><p>因此可以形成一个有边界的判断：<strong>对齐检查点是长时恢复的重要机制，却不是完整的恢复合同。可问责恢复还必须把检查点绑定到原执行发生、当前恢复权限、策略版本和外部影响台账。</strong></p><h2 id="对齐回退先解决内部因果错位" tabindex="-1">对齐回退先解决内部因果错位 <a class="header-anchor" href="#对齐回退先解决内部因果错位" aria-label="Permalink to &quot;对齐回退先解决内部因果错位&quot;">​</a></h2><p>只恢复文件，不恢复上下文，智能体可能依据已经过时的观察继续推理；只恢复上下文，不恢复文件，推理又会面对未来状态。两者分离会形成内部“分裂”：记忆中的世界和工具实际可见的世界并非同一时刻。</p><p>对齐回退让智能体上下文和受控环境指向同一个因果位置。保留有效的执行前缀，再结合失败记忆，可以避免完全重启时丢掉已经取得的进展，也减少在错误状态上继续扩散。</p><p>论文报告的结果支持这一机制在被评估的工程任务中有效。以其列出的模型结果为例，对齐回退相对继续执行获得更高的任务成功与清单进度。不过，这些数字是特定基准和策略下的来源报告，不是对任意企业流程的普遍保证。</p><h2 id="边界之外的影响不会自动回退" tabindex="-1">边界之外的影响不会自动回退 <a class="header-anchor" href="#边界之外的影响不会自动回退" aria-label="Permalink to &quot;边界之外的影响不会自动回退&quot;">​</a></h2><p>工作区快照能恢复目录树，却无法撤销已发送的消息、已经创建的云资源、完成的付款或人类批准。即使某次调用返回失败，它也可能已经在外部系统产生影响。恢复者若只看本地快照，便可能把已经发生的动作当作尚未发生。</p><p>所以，恢复前必须建立“影响边界”。每个有外部影响的动作至少需要记录：属于哪次工作发生、请求的稳定身份、外部系统回执、已知结果、是否可重试、补偿方式以及尚未确定的部分。台账不必保存敏感正文，但必须能区分未执行、已提交、结果未知和已补偿。</p><p>这类记录并非证明一切安全，而是防止状态回退抹去影响事实。对于不可重复安全执行的动作，结果未知本身就应阻止自动重放。</p><h2 id="恢复还必须重新取得权限" tabindex="-1">恢复还必须重新取得权限 <a class="header-anchor" href="#恢复还必须重新取得权限" aria-label="Permalink to &quot;恢复还必须重新取得权限&quot;">​</a></h2><p>即使外部影响记录完整，恢复者也未必仍然有权继续。任务可能已经取消，用户权限可能被收回，策略可能更新，或者新的执行者不能访问旧检查点中的敏感上下文。</p><p>完整的恢复准入至少需要五项绑定：选中的检查点、被中断的执行轮次、当前恢复主体、适用的策略版本、检查点边界之外的影响状态。它们应共享稳定的工作发生身份。恢复并非把旧权限从快照里解冻，而是对当前条件重新作出授权决定。</p><p>通过准入后，系统还要为恢复后的执行创建新的轮次身份，并保留它与旧轮次、所选检查点和授权决定的关系。这样既能延续同一项工作，也不会把两次执行压成一条无法审计的记录。</p><h2 id="台账不能替代幂等与补偿" tabindex="-1">台账不能替代幂等与补偿 <a class="header-anchor" href="#台账不能替代幂等与补偿" aria-label="Permalink to &quot;台账不能替代幂等与补偿&quot;">​</a></h2><p>外部影响台账只提供事实面。它不会自动让付款可重试，也不会撤回已经发送的邮件。执行层仍需选择稳定的幂等键、影响查询、补偿动作或人工接受。</p><p>局部编码环境可能没有重要的外部影响，此时精简合同是合理的。但这种部署假设必须写明，不能从“这个任务全在版本库里”推广到消息、云管理或审批流程。</p><p>恢复合同也不应承诺恰好一次执行，除非外部系统提供足够的事务与回执能力。更诚实的目标是：已知影响不被重复，未知影响不会被静默重放，无法自动协调的情况进入明确的人工门禁。</p><h2 id="证据边界与开放问题" tabindex="-1">证据边界与开放问题 <a class="header-anchor" href="#证据边界与开放问题" aria-label="Permalink to &quot;证据边界与开放问题&quot;">​</a></h2><p>现有证据来自受控工程任务的一项主要研究。它没有证明企业级持久性、秘密隔离或任意工具的安全恢复，也没有评估本文提出的完整恢复合同。本文的合同是从对齐回退机制与其明确边界推导出的治理设计。</p><p>仍需回答的问题包括：谁有权选择回退点；如何防止回退删除不利证据；外部回执应如何绑定执行轮次；策略变化到什么程度必须把恢复视为新的工作发生；以及敏感上下文在新恢复主体面前如何重新授权。</p><p>检查点告诉系统从哪里恢复。恢复合同还必须回答：是谁在恢复、依据哪项当前授权、哪些影响已经越过回退边界，以及继续执行会不会重复现实世界中的动作。</p><p><strong>一手来源：</strong> <a href="https://arxiv.org/abs/2608.14380" target="_blank" rel="noreferrer">对齐回退研究</a></p>',26))])}const g=t(s,[["render",p]]);export{y as __pageData,g as default};
